const raw = String($json.text || '');
const fail = {
  status: 'input_error',
  match_score: null,
  matched_requirements: [],
  partial_matches: [],
  not_evidenced: [],
  strengths: [],
  recruiter_questions: [],
  review_note: 'Provide readable CV text and job description'
};
const s = raw.indexOf('{');
const e = raw.lastIndexOf('}');
if (s === -1 || e === -1) {
  return { json: { ...fail, review_note: 'Model output could not be parsed. Rerun or review the CV manually' } };
}
let r;
try {
  r = JSON.parse(raw.slice(s, e + 1));
} catch (err) {
  return { json: { ...fail, review_note: 'Model output could not be parsed. Rerun or review the CV manually' } };
}
const matched = Array.isArray(r.matched_requirements) ? r.matched_requirements : [];
const partial = Array.isArray(r.partial_matches) ? r.partial_matches : [];
const missing = Array.isArray(r.not_evidenced) ? r.not_evidenced : [];
const total = matched.length + partial.length + missing.length;
if (r.status === 'input_error' || total === 0) {
  return { json: fail };
}
const equalWeightScore = Math.round(((matched.length + 0.5 * partial.length) / total) * 100);
const modelScore = Number(r.match_score);
const useModel = Number.isFinite(modelScore) && modelScore >= 0 && modelScore <= 100 && Math.abs(modelScore - equalWeightScore) <= 10;
return {
  json: {
    status: 'ok',
    match_score: useModel ? Math.round(modelScore) : equalWeightScore,
    matched_requirements: matched,
    partial_matches: partial,
    not_evidenced: missing,
    strengths: Array.isArray(r.strengths) ? r.strengths : [],
    recruiter_questions: Array.isArray(r.recruiter_questions) ? r.recruiter_questions : [],
    review_note: 'Human recruiter review required'
  }
};

